-- Initial production schema for the two-app Client + Engineer platform.
CREATE TYPE "Role" AS ENUM ('CLIENT', 'ENGINEER', 'ADMIN');
CREATE TYPE "AccountStatus" AS ENUM ('PENDING_VERIFICATION', 'ACTIVE', 'SUSPENDED', 'DEACTIVATED');
CREATE TYPE "VerificationStatus" AS ENUM ('NOT_SUBMITTED', 'PENDING', 'UNDER_REVIEW', 'VERIFIED', 'REJECTED');
CREATE TYPE "RequestStatus" AS ENUM ('DRAFT', 'PENDING', 'ACCEPTED', 'DECLINED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED');

CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT, "phoneNumber" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "status" "AccountStatus" NOT NULL DEFAULT 'PENDING_VERIFICATION', "isPhoneVerified" BOOLEAN NOT NULL DEFAULT false, "isEmailVerified" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3), CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserRole" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "role" "Role" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "UserRole_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClientProfile" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "fullName" TEXT NOT NULL, "avatarUrl" TEXT, "city" TEXT, "state" TEXT, "latitude" DOUBLE PRECISION, "longitude" DOUBLE PRECISION, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ClientProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProfessionalProfile" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "fullName" TEXT NOT NULL, "avatarUrl" TEXT, "coverUrl" TEXT, "title" TEXT NOT NULL, "bio" TEXT, "yearsOfExperience" INTEGER NOT NULL DEFAULT 0, "verificationStatus" "VerificationStatus" NOT NULL DEFAULT 'NOT_SUBMITTED', "averageRating" DOUBLE PRECISION NOT NULL DEFAULT 0.0, "totalReviewsCount" INTEGER NOT NULL DEFAULT 0, "isAvailable" BOOLEAN NOT NULL DEFAULT true, "baseCity" TEXT NOT NULL, "baseState" TEXT NOT NULL, "baseLatitude" DOUBLE PRECISION NOT NULL, "baseLongitude" DOUBLE PRECISION NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProfessionalProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EngineerProfile" ("consultationFee" DOUBLE PRECISION, "id" TEXT NOT NULL, "professionalProfileId" TEXT NOT NULL, "licenseNumber" TEXT, "qualificationDegree" TEXT NOT NULL, "institution" TEXT NOT NULL, "graduationYear" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "EngineerProfile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AvailabilitySlot" ("id" TEXT NOT NULL, "professionalProfileId" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3) NOT NULL, "isAvailable" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AvailabilitySlot_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ServiceArea" ("id" TEXT NOT NULL, "professionalProfileId" TEXT NOT NULL, "name" TEXT NOT NULL, "city" TEXT, "latitude" DOUBLE PRECISION, "longitude" DOUBLE PRECISION, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ServiceArea_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Specialization" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "description" TEXT, "iconUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Specialization_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EngineerSpecialization" ("engineerProfileId" TEXT NOT NULL, "specializationId" TEXT NOT NULL, CONSTRAINT "EngineerSpecialization_pkey" PRIMARY KEY ("engineerProfileId", "specializationId"));
CREATE TABLE "EngineerRequest" ("id" TEXT NOT NULL, "clientProfileId" TEXT NOT NULL, "engineerProfileId" TEXT NOT NULL, "projectTitle" TEXT NOT NULL, "projectDescription" TEXT NOT NULL, "propertyType" TEXT NOT NULL, "projectSizeSqFt" DOUBLE PRECISION, "locationAddress" TEXT NOT NULL, "latitude" DOUBLE PRECISION NOT NULL, "longitude" DOUBLE PRECISION NOT NULL, "preferredStartDate" TIMESTAMP(3), "budgetEstimate" DOUBLE PRECISION, "status" "RequestStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "EngineerRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RequestStatusHistory" ("id" TEXT NOT NULL, "engineerRequestId" TEXT NOT NULL, "fromStatus" "RequestStatus", "toStatus" "RequestStatus" NOT NULL, "changedByUserId" TEXT NOT NULL, "reason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RequestStatusHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Review" ("id" TEXT NOT NULL, "clientProfileId" TEXT NOT NULL, "professionalProfileId" TEXT NOT NULL, "engineerRequestId" TEXT, "rating" INTEGER NOT NULL, "comment" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Review_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Conversation" ("id" TEXT NOT NULL, "engineerRequestId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Conversation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ConversationParticipant" ("conversationId" TEXT NOT NULL, "userId" TEXT NOT NULL, "joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastReadAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ConversationParticipant_pkey" PRIMARY KEY ("conversationId", "userId"));
CREATE TABLE "Message" ("id" TEXT NOT NULL, "conversationId" TEXT NOT NULL, "senderUserId" TEXT NOT NULL, "content" TEXT NOT NULL, "attachmentUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE TABLE "VerificationDocument" ("id" TEXT NOT NULL, "professionalProfileId" TEXT NOT NULL, "documentType" TEXT NOT NULL, "documentUrl" TEXT NOT NULL, "isVerified" BOOLEAN NOT NULL DEFAULT false, "uploadedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "VerificationDocument_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PortfolioItem" ("id" TEXT NOT NULL, "professionalProfileId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "imageUrl" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PortfolioItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Notification" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "kind" TEXT NOT NULL DEFAULT 'system', "title" TEXT NOT NULL, "body" TEXT NOT NULL, "data" JSONB, "isRead" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL, "userId" TEXT, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Favorite" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "professionalId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Favorite_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "refreshTokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OtpChallenge" ("phoneNumber" TEXT NOT NULL, "codeHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "requestedAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "OtpChallenge_pkey" PRIMARY KEY ("phoneNumber"));

CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "User_phoneNumber_key" ON "User"("phoneNumber");
CREATE UNIQUE INDEX "UserRole_userId_role_key" ON "UserRole"("userId", "role");
CREATE UNIQUE INDEX "ClientProfile_userId_key" ON "ClientProfile"("userId");
CREATE UNIQUE INDEX "ProfessionalProfile_userId_key" ON "ProfessionalProfile"("userId");
CREATE UNIQUE INDEX "EngineerProfile_professionalProfileId_key" ON "EngineerProfile"("professionalProfileId");
CREATE UNIQUE INDEX "EngineerProfile_licenseNumber_key" ON "EngineerProfile"("licenseNumber");
CREATE INDEX "AvailabilitySlot_professionalProfileId_startsAt_idx" ON "AvailabilitySlot"("professionalProfileId", "startsAt");
CREATE INDEX "ServiceArea_professionalProfileId_idx" ON "ServiceArea"("professionalProfileId");
CREATE UNIQUE INDEX "Specialization_name_key" ON "Specialization"("name");
CREATE UNIQUE INDEX "Specialization_slug_key" ON "Specialization"("slug");
CREATE INDEX "EngineerRequest_clientProfileId_status_idx" ON "EngineerRequest"("clientProfileId", "status");
CREATE INDEX "EngineerRequest_engineerProfileId_status_idx" ON "EngineerRequest"("engineerProfileId", "status");
CREATE UNIQUE INDEX "Review_engineerRequestId_key" ON "Review"("engineerRequestId");
CREATE INDEX "Conversation_engineerRequestId_idx" ON "Conversation"("engineerRequestId");
CREATE INDEX "Message_conversationId_createdAt_idx" ON "Message"("conversationId", "createdAt");
CREATE INDEX "Notification_userId_isRead_createdAt_idx" ON "Notification"("userId", "isRead", "createdAt");
CREATE UNIQUE INDEX "Favorite_userId_professionalId_key" ON "Favorite"("userId", "professionalId");
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");

ALTER TABLE "UserRole" ADD CONSTRAINT "UserRole_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ClientProfile" ADD CONSTRAINT "ClientProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProfessionalProfile" ADD CONSTRAINT "ProfessionalProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EngineerProfile" ADD CONSTRAINT "EngineerProfile_professionalProfileId_fkey" FOREIGN KEY ("professionalProfileId") REFERENCES "ProfessionalProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AvailabilitySlot" ADD CONSTRAINT "AvailabilitySlot_professionalProfileId_fkey" FOREIGN KEY ("professionalProfileId") REFERENCES "ProfessionalProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ServiceArea" ADD CONSTRAINT "ServiceArea_professionalProfileId_fkey" FOREIGN KEY ("professionalProfileId") REFERENCES "ProfessionalProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EngineerSpecialization" ADD CONSTRAINT "EngineerSpecialization_engineerProfileId_fkey" FOREIGN KEY ("engineerProfileId") REFERENCES "EngineerProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EngineerSpecialization" ADD CONSTRAINT "EngineerSpecialization_specializationId_fkey" FOREIGN KEY ("specializationId") REFERENCES "Specialization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EngineerRequest" ADD CONSTRAINT "EngineerRequest_clientProfileId_fkey" FOREIGN KEY ("clientProfileId") REFERENCES "ClientProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EngineerRequest" ADD CONSTRAINT "EngineerRequest_engineerProfileId_fkey" FOREIGN KEY ("engineerProfileId") REFERENCES "EngineerProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "RequestStatusHistory" ADD CONSTRAINT "RequestStatusHistory_engineerRequestId_fkey" FOREIGN KEY ("engineerRequestId") REFERENCES "EngineerRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Review" ADD CONSTRAINT "Review_clientProfileId_fkey" FOREIGN KEY ("clientProfileId") REFERENCES "ClientProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Review" ADD CONSTRAINT "Review_professionalProfileId_fkey" FOREIGN KEY ("professionalProfileId") REFERENCES "ProfessionalProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Review" ADD CONSTRAINT "Review_engineerRequestId_fkey" FOREIGN KEY ("engineerRequestId") REFERENCES "EngineerRequest"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Conversation" ADD CONSTRAINT "Conversation_engineerRequestId_fkey" FOREIGN KEY ("engineerRequestId") REFERENCES "EngineerRequest"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ConversationParticipant" ADD CONSTRAINT "ConversationParticipant_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ConversationParticipant" ADD CONSTRAINT "ConversationParticipant_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_senderUserId_fkey" FOREIGN KEY ("senderUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "VerificationDocument" ADD CONSTRAINT "VerificationDocument_professionalProfileId_fkey" FOREIGN KEY ("professionalProfileId") REFERENCES "ProfessionalProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PortfolioItem" ADD CONSTRAINT "PortfolioItem_professionalProfileId_fkey" FOREIGN KEY ("professionalProfileId") REFERENCES "ProfessionalProfile"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Favorite" ADD CONSTRAINT "Favorite_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
